using System;using System.Drawing;using System.IO;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
partial class Layer {public bool Locked,PermanentlyLocked;public bool IsLocked{get{return Locked||PermanentlyLocked;}}}
partial class Document {
 public bool HasBase {get{return Layers.Any(l=>l.PermanentlyLocked);}}
 public void CreateBaseLayers(){var baseLayer=new Layer("BASE LAYER",Width,Height){Locked=true,PermanentlyLocked=true};var colour=new Layer("BASE COLOUR",Width,Height){Locked=true};using(var g=Graphics.FromImage(colour.Image))g.Clear(Color.White);Layers.Insert(0,baseLayer);Layers.Insert(1,colour);Active=2;}
}
partial class Studio {
 void ToggleLayerLock(int index){if(canvas.Doc==null||index<0||index>=layers.Items.Count)return;var layer=SelectLayerIconTarget(index);if(layer==null)return;if(layer.PermanentlyLocked)return;layer.Locked=!layer.Locked;canvas.CancelVector();Changed();RefreshLayers();}
 public void TestVersion32(){using(var doc=new Document(CanvasPreset.All[0])){if(doc.Layers.Count!=3||doc.Active!=2||doc.Selected.Name!="Layer 1"||doc.Selected.IsLocked||doc.Layers[0].Name!="BASE LAYER"||!doc.Layers[0].PermanentlyLocked||doc.Layers[0].Image.GetPixel(0,0).A!=0||doc.Layers[1].Name!="BASE COLOUR"||!doc.Layers[1].IsLocked||doc.Layers[1].Image.GetPixel(0,0).ToArgb()!=Color.White.ToArgb())throw new Exception("New layer stack");doc.Layers[1].Visible=false;using(var flat=doc.Flatten())if(flat.GetPixel(0,0).A!=0)throw new Exception("Transparent base export");}
 SetDocument(new Document(CanvasPreset.All[0]),null);canvas.Zoom=1;canvas.Offset=PointF.Empty;layers.TestLock(1);if(canvas.Doc.Selected.Locked)throw new Exception("Unlock colour");layers.TestLock(1);if(!canvas.Doc.Selected.Locked)throw new Exception("Lock colour");var image=Document.Png(canvas.Doc.Selected.Image);int history=undo.Count;canvas.TestDrag(new Point(100,100),new Point(200,100));canvas.FillAt(new PointF(10,10));ClearLayer();FillLayer();if(undo.Count!=history||!image.SequenceEqual(Document.Png(canvas.Doc.Selected.Image)))throw new Exception("Locked pixel editing");layers.TestLock(2);if(!canvas.Doc.Selected.PermanentlyLocked||!canvas.Doc.Selected.IsLocked)throw new Exception("Permanent lock");MoveLayer(1);RenameLayer();DeleteLayer();if(canvas.Doc.Layers[0]!=canvas.Doc.Selected||canvas.Doc.Layers[0].Name!="BASE LAYER")throw new Exception("Base protection");string file=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(file);using(var loaded=Document.Load(file))if(!loaded.Layers[0].PermanentlyLocked||!loaded.Layers[1].Locked)throw new Exception("Lock persistence");}finally{if(File.Exists(file))File.Delete(file);}layers.SelectedIndex=0;AddTypedLayer(true);vectorMode.SelectedItem="Line";canvas.TestDrag(new Point(100,100),new Point(300,100));var vector=canvas.Doc.Selected;vector.Locked=true;canvas.DeleteVector();canvas.ChangeVectorWeight(12);canvas.TestDrag(new Point(100,200),new Point(300,200));if(vector.Vectors.Count!=1||vector.Vectors[0].Width==12)throw new Exception("Locked vector editing");
 var shape=new VectorShape{Kind="Curvature pen",Points=new System.Collections.Generic.List<PointF>{new PointF(0,0),new PointF(100,50),new PointF(200,0)}};float old=StrokeSession.Distance(PointF.Empty,shape.PointHandles(1)[0]);shape.SetPointHandle(1,1,new PointF(140,90));var handles=shape.PointHandles(1);if(Math.Abs(handles[0].X*handles[1].Y-handles[0].Y*handles[1].X)>.01||handles[0].X*handles[1].X+handles[0].Y*handles[1].Y>=0||Math.Abs(StrokeSession.Distance(PointF.Empty,handles[0])-old)>.01)throw new Exception("Linked smooth handles");dirty=false;
 }
 public void PreviewBaseLayers(){SetDocument(new Document(CanvasPreset.All[0]),null);canvas.Fit();using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"base-layers-preview.png"));}dirty=false;}
}
partial class LayerList {
 public Action<int> LockClicked;
 public void TestLock(int index){var rect=GetItemRectangle(index);OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,42,rect.Top+rect.Height/2,0));}
 void PaintLock(Graphics g,Layer layer,Rectangle bounds,Color ink){float x=bounds.X+36,y=bounds.Y+bounds.Height/2f;using(var pen=new Pen(ink,1.5f)){g.DrawRectangle(pen,x,y-1,12,10);if(layer.IsLocked)g.DrawArc(pen,x+2,y-10,8,14,180,180);else g.DrawArc(pen,x+5,y-10,8,14,175,185);g.DrawLine(pen,x+6,y+2,x+6,y+6);if(layer.PermanentlyLocked)g.DrawLine(pen,x+2,y+12,x+10,y+12);}}
}
}
